.darma-loader-darma-b9-pendulum-wave { --accent: var(--loader-color, #6366f1); --accent-2: var(--loader-secondary-color, #f472b6); width: var(--loader-size, 88px); height: var(--loader-size, 88px); display: flex; justify-content: space-between; }
.darma-loader-darma-b9-pendulum-wave span { position: relative; width: calc(var(--loader-size, 88px) * .04); background: linear-gradient(color-mix(in srgb, var(--accent) 30%, transparent), transparent); border-radius: 3px; transform-origin: 50% 0; }
.darma-loader-darma-b9-pendulum-wave span::after { content: ''; position: absolute; bottom: 0; left: 50%; width: calc(var(--loader-size, 88px) * .13); height: calc(var(--loader-size, 88px) * .13); margin-left: calc(var(--loader-size, 88px) * -.065); border-radius: 50%; background: var(--accent); }
.darma-loader-darma-b9-pendulum-wave span:nth-child(even)::after { background: var(--accent-2); }
.darma-loader-darma-b9-pendulum-wave span:nth-child(1) { height: 100%; animation: darma-loader-darma-b9-pendulum-wave-pw calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
.darma-loader-darma-b9-pendulum-wave span:nth-child(2) { height: 90%; animation: darma-loader-darma-b9-pendulum-wave-pw calc(var(--loader-speed, 1s) * 1.86) ease-in-out infinite; }
.darma-loader-darma-b9-pendulum-wave span:nth-child(3) { height: 80%; animation: darma-loader-darma-b9-pendulum-wave-pw calc(var(--loader-speed, 1s) * 1.72) ease-in-out infinite; }
.darma-loader-darma-b9-pendulum-wave span:nth-child(4) { height: 70%; animation: darma-loader-darma-b9-pendulum-wave-pw calc(var(--loader-speed, 1s) * 1.58) ease-in-out infinite; }
.darma-loader-darma-b9-pendulum-wave span:nth-child(5) { height: 60%; animation: darma-loader-darma-b9-pendulum-wave-pw calc(var(--loader-speed, 1s) * 1.44) ease-in-out infinite; }
@keyframes darma-loader-darma-b9-pendulum-wave-pw { 0%, 100% { transform: rotate(30deg); } 50% { transform: rotate(-30deg); } }

